export function isMobileBrowser({userAgent='',platform='',maxTouchPoints=0,userAgentData}={}){
 return userAgentData?.mobile===true||/Android|iPhone|iPad|iPod|IEMobile|Opera Mini/i.test(userAgent)||(platform==='MacIntel'&&maxTouchPoints>1);
}
export function localWorkspaceNoticeMarkup(){return '<h2>Local workspace requires a PC</h2><p>Connecting a local workspace is currently available only when you use Mokel on a PC. Files stored on this phone cannot be connected yet.</p><p>You can connect a GitHub workspace on mobile to work with repository files. GitHub authorization is required; local terminal commands are not available.</p><button class="button primary full" data-action="workspace-github">Connect to GitHub workspace</button><button class="button full" data-action="modal-close">Close</button>';}
export function mobileNoticeMarkup(){return '<h2>Agent Mode on mobile</h2><p>Agent Mode is not yet supported in standard mobile browsers. API Mode remains available.</p><p><strong>Mokel Mobile App — coming soon.</strong> The app is not available to download yet.</p><p>On Android, you can explore a browser that supports extensions:</p><ul class="about-list"><li><a href="https://www.quetta.net/downloads" target="_blank" rel="noopener noreferrer">Quetta</a> — supports Chromium extensions.</li><li><a href="https://www.mozilla.org/firefox/browsers/mobile/android/" target="_blank" rel="noopener noreferrer">Firefox for Android</a> — supports Firefox add-ons.</li><li><a href="https://www.microsoft.com/edge/download/insider" target="_blank" rel="noopener noreferrer">Microsoft Edge Canary</a> — experimental Android browser with custom-extension support.</li></ul><p class="small-note">Extension support alone does not guarantee that the Mokel Bridge will work. Android Bridge compatibility is still being tested. Use a desktop browser for supported Agent Mode and local PC access.</p><button class="button full" data-action="modal-close">Continue anyway</button>';}
